#!/bin/sh
# Remake the kitty vectors with the installed tools, in the container:
#   sh tests/vectors/kitty/regen.sh
# The captures go through ptycap.py, which answers the tools' queries as
# havoc does today; the images are generated by mkimg.py. Both live in
# tests/tools (they come with the sixel test branch). The output differs a
# little between tool versions (see README), so a regenerated set has to be
# looked at before it replaces the committed one: set OUT for another place.
set -e
top=$(cd "$(dirname "$0")/../../.." && pwd)
tools=${TOOLS:-$top/tests/tools}
out=${OUT:-$top/tests/vectors/kitty}
for f in ptycap.py mkimg.py; do
	[ -f "$tools/$f" ] || { echo "regen: $tools/$f is missing" >&2; exit 1; }
done
img=$(mktemp -d)
trap 'rm -rf "$img"' EXIT
python3 -I "$tools/mkimg.py" "$img"
C="python3 -I $tools/ptycap.py"
G=$img/grad64x48.png
A=$img/alpha64x48.png
P=$img/pattern240x160.png
run() { name=$1; shift; prof=$1; shift; $C --profile "$prof" --out "$out/$name.bin" "$@"; rm -f "$out/$name.bin.queries"; }

run chafa-kitty-grad havoc-now -- chafa -f kitty $G
run chafa-kitty-alpha havoc-now -- chafa -f kitty $A
run timg-kitty havoc-now -- timg -p kitty $G
run timg-kitty-pattern havoc-now -- timg -p kitty $P
run icat-stream kitty -- kitten icat --transfer-mode=stream $G
run icat-stream-pattern kitty -- kitten icat --transfer-mode=stream $P
run icat-detect kitty -- kitten icat --detect-support
run icat-kitty kitty --timeout 6 -- kitten icat $G
run mpv-kitty-shm havoc-now --timeout 20 -- mpv --really-quiet --no-audio --frames=2 --vo=kitty --vo-kitty-use-shm=yes av://lavfi:testsrc=size=96x64:rate=5
